:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #6c5ce7;
  --accent-hover: #7d6ff0;
  --cell-off: #3a3a55;
  --cell-on: #fdcb6e;
  --cell-on-hover: #ffe08a;
  --focus: #a29bfe;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 1rem;
}

.card {
  background: var(--card-bg);
  border-radius: 1.5rem;
  padding: 2rem;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
  max-width: 400px;
  width: 100%;
  text-align: center;
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 0.5rem;
  letter-spacing: 0.05em;
}

.subtitle {
  font-size: 0.95rem;
  color: #b0b0c0;
  margin-bottom: 1.5rem;
  line-height: 1.4;
}

.board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

.cell {
  aspect-ratio: 1;
  border: none;
  border-radius: 0.75rem;
  background: var(--cell-off);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  font-size: 1rem;
  color: transparent;
}

.cell.on {
  background: var(--cell-on);
  box-shadow: 0 0 12px var(--cell-on);
}

.cell:hover {
  filter: brightness(1.2);
}

.cell:active {
  transform: scale(0.95);
}

.cell:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.status {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
  font-size: 1.1rem;
  min-height: 2rem;
}

.moves {
  font-weight: 600;
}

.win-message {
  color: var(--cell-on);
  font-weight: 700;
  font-size: 1.2rem;
}

.btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 0.75rem;
  padding: 0.75rem 1.5rem;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  width: 100%;
}

.btn:hover {
  background: var(--accent-hover);
}

.btn:active {
  transform: scale(0.97);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

@media (max-width: 360px) {
  .card {
    padding: 1.5rem;
  }
  .board {
    gap: 0.5rem;
  }
  h1 {
    font-size: 1.5rem;
  }
}

const SIZE = 3;
const boardEl = document.getElementById('board');
const movesEl = document.getElementById('moves');
const winEl = document.getElementById('win-message');
const newBtn = document.getElementById('new-puzzle');

let grid = [];
let moves = 0;
let won = false;

function createBoard() {
  boardEl.innerHTML = '';
  for (let r = 0; r < SIZE; r++) {
    for (let c = 0; c < SIZE; c++) {
      const btn = document.createElement('button');
      btn.className = 'cell';
      btn.type = 'button';
      btn.dataset.r = r;
      btn.dataset.c = c;
      btn.setAttribute('aria-label', `Cell ${r+1},${c+1}`);
      btn.addEventListener('click', () => handleClick(r, c));
      boardEl.appendChild(btn);
    }
  }
}

function toggleCell(r, c) {
  if (r < 0 || r >= SIZE || c < 0 || c >= SIZE) return;
  grid[r][c] = !grid[r][c];
}

function handleClick(r, c) {
  if (won) return;
  toggleCell(r, c);
  toggleCell(r-1, c);
  toggleCell(r+1, c);
  toggleCell(r, c-1);
  toggleCell(r, c+1);
  moves++;
  updateUI();
  if (isSolved()) {
    won = true;
    winEl.textContent = 'You win!';
  }
}

function isSolved() {
  return grid.every(row => row.every(cell => !cell));
}

function updateUI() {
  const cells = boardEl.children;
  for (let r = 0; r < SIZE; r++) {
    for (let c = 0; c < SIZE; c++) {
      const idx = r * SIZE + c;
      const on = grid[r][c];
      cells[idx].classList.toggle('on', on);
      cells[idx].setAttribute('aria-pressed', String(on));
    }
  }
  movesEl.textContent = `Moves: ${moves}`;
}

function newPuzzle() {
  grid = Array.from({ length: SIZE }, () => Array(SIZE).fill(false));
  moves = 0;
  won = false;
  winEl.textContent = '';
  // Apply random moves from solved state
  const numMoves = 5 + Math.floor(Math.random() * 5);
  for (let i = 0; i < numMoves; i++) {
    const r = Math.floor(Math.random() * SIZE);
    const c = Math.floor(Math.random() * SIZE);
    toggleCell(r, c);
    toggleCell(r-1, c);
    toggleCell(r+1, c);
    toggleCell(r, c-1);
    toggleCell(r, c+1);
  }
  updateUI();
}

createBoard();
newPuzzle();
newBtn.addEventListener('click', newPuzzle);
